import {shuffled} from './learning.js?v=74a';
export const PHONICS={A:{sound:'æ',hint:'short a, as at the start of ant',words:['ant','axe']},B:{sound:'b',hint:'a short b sound, without adding uh',words:['bear','ball']},C:{sound:'k',hint:'the hard c sound, as at the start of cat',words:['cat','cut']},D:{sound:'d',hint:'a short d sound, without adding uh',words:['dog','dig']},E:{sound:'ɛ',hint:'short e, as at the start of egg',words:['elephant','egg']},F:{sound:'f',hint:'a continuous f sound, as at the start of fish',words:['fish','fin']},G:{sound:'g',hint:'the hard g sound, as at the start of goose',words:['goose','gate']},H:{sound:'h',hint:'a gentle breath, as at the start of hen',words:['hen','hat']}};
export const PHONICS_LETTERS=Object.keys(PHONICS);
export const PHONICS_WORDS=Object.values(PHONICS).flatMap(x=>x.words);
export const PHONICS_TAGS=['Letter form confusion','Letter name versus sound','Initial-sound confusion','Unfamiliar word','Pronunciation to revisit','Movement or controls','Favourite mission'];
export function validPhonicsPool(pool){return [...new Set(Array.isArray(pool)?pool:[])].filter(x=>PHONICS[x]);}
export function choosePhonicsPair(pool,previous=[],random=Math.random){const enabled=validPhonicsPool(pool);if(enabled.length<2)throw Error('Enable at least two letters.');let pairs=[];for(let i=0;i<enabled.length;i++)for(let j=i+1;j<enabled.length;j++)pairs.push([enabled[i],enabled[j]]);const old=[...previous].sort().join('');if(pairs.length>1)pairs=pairs.filter(p=>[...p].sort().join('')!==old);return [...pairs[Math.floor(random()*pairs.length)]];}
export function phonicsWords(pair){return pair.flatMap(letter=>PHONICS[letter].words);}
export function letterForWord(word){return PHONICS_LETTERS.find(letter=>PHONICS[letter].words.includes(word));}
export function createPhonicsTasks(pair,random=Math.random,cardCount=3){if(pair.length!==2||new Set(pair).size!==2||pair.some(l=>!PHONICS[l]))throw Error('Choose two different supported letters.');const sounds=shuffled([...pair,...pair],random).map(letter=>({kind:'sound-search',letter,excluded:[]}));let chosen=pair.map(l=>PHONICS[l].words[Math.floor(random()*2)]);if(cardCount!==2)chosen.push(shuffled(phonicsWords(pair).filter(w=>!chosen.includes(w)),random)[0]);const cards=shuffled(chosen,random).map(word=>({kind:'card-word',word,letter:letterForWord(word)}));return [...sounds,...cards].map((task,id)=>({...task,id}));}
export function phonicsMatches(task,item){if(!task||!item||item.kind!=='word')return false;if(task.kind==='sound-search')return PHONICS[task.letter].words.includes(item.word)&&!(task.excluded||[]).includes(item.word);return task.kind==='card-word'&&item.word===task.word;}
export function phonicsSpeakingTarget(task){const word=task.foundWord||task.word||'';return ['cut','dig'].includes(word)?`I can ${word}.`:`I found ${['ant','axe','elephant','egg'].includes(word)?'an':'a'} ${word}.`;}
export function phonicsPicture(word){const icons={ant:'🐜',axe:'🪓',bear:'🧸',ball:'⚽',cat:'🐈',cut:'✂️',dog:'🐕',elephant:'🐘',egg:'🥚',fish:'🐟',goose:'🪿',gate:'🚪',hen:'🐓',hat:'👒'};let icon=icons[word]?`<text x="150" y="178" font-size="142" text-anchor="middle" font-family="Apple Color Emoji,Segoe UI Emoji,sans-serif">${icons[word]}</text>`:word==='fin'?'<path d="M75 200 153 45 226 200Z" fill="#e6a451" stroke="#b57c38" stroke-width="7"/><path d="m153 65-30 124m30-124 14 124m-14-124 48 124" stroke="#ffe2a3" stroke-width="5"/>':'<path d="m101 49 35-16 52 124-29 13Z" fill="#bf925d"/><path d="m131 148 65-27q45 78-14 99-41 13-51-72" fill="#8cb3b6" stroke="#527e83" stroke-width="7"/>';
return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 300 250" role="img" aria-label="Picture of ${word}"><circle cx="150" cy="125" r="113" fill="#f7eed1"/>${icon}</svg>`;}
